package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TempRec struct { // 01 TEMP-REC, 8 bytes
	TcSensor string          // PIC X(4) @0 len=4
	TcF      decimal.Decimal // PIC 9(3)V9 @4 len=4
}

// Standalone working-storage items
var WsEofFlag string = "N"                        // PIC X len=1 = "N"
var WsC decimal.Decimal = decimal.NewFromInt(0)   // PIC S9(3)V99 len=5 = 0
var WsFreeze int64 = 0                            // PIC 99 len=2 = 0
var WsCount int64 = 0                             // PIC 99 len=2 = 0
var WsFEd string                                  // PIC ZZ9.9 len=5
var WsCEd string                                  // PIC -ZZ9.99 len=7

var tempFile *os.File
var scanner *bufio.Scanner
var TempRecInst TempRec

func InputDone() bool { return WsEofFlag == "Y" }

func pow10(n int) int64 {
	p := int64(1)
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}

func formatZZ9_9(v decimal.Decimal) string {
	intWidth := 3
	fracWidth := 1
	totalPow := pow10(intWidth + fracWidth) // 10000
	scaled := v.Shift(int32(fracWidth)).Truncate(0)
	scaledInt := scaled.IntPart()
	if scaledInt < 0 {
		scaledInt = -scaledInt
	}
	if scaledInt >= totalPow {
		scaledInt %= totalPow
	}
	powFrac := pow10(fracWidth)
	intPart := scaledInt / powFrac
	fracPart := scaledInt % powFrac
	integerStr := fmt.Sprintf("%0*d", intWidth, intPart)
	b := []byte(integerStr)
	firstNonZero := -1
	for i, c := range b {
		if c != '0' {
			firstNonZero = i
			break
		}
	}
	if firstNonZero == -1 {
		for i := 0; i < intWidth-1; i++ {
			b[i] = ' '
		}
	} else {
		for i := 0; i < firstNonZero; i++ {
			if i < intWidth-1 {
				b[i] = ' '
			}
		}
	}
	integerFormatted := string(b)
	fracStr := fmt.Sprintf("%0*d", fracWidth, fracPart)
	return integerFormatted + "." + fracStr
}

func formatMinusZZ9_99(v decimal.Decimal) string {
	if v.IsZero() {
		v = decimal.Zero
	}
	signChar := ' '
	absV := v
	if v.Sign() < 0 {
		signChar = '-'
		absV = v.Abs()
	}
	intWidth := 3
	fracWidth := 2
	totalPow := pow10(intWidth + fracWidth) // 100000
	scaled := absV.Shift(int32(fracWidth)).Truncate(0)
	scaledInt := scaled.IntPart()
	if scaledInt >= totalPow {
		scaledInt %= totalPow
	}
	powFrac := pow10(fracWidth)
	intPart := scaledInt / powFrac
	fracPart := scaledInt % powFrac
	integerStr := fmt.Sprintf("%0*d", intWidth, intPart)
	b := []byte(integerStr)
	firstNonZero := -1
	for i, c := range b {
		if c != '0' {
			firstNonZero = i
			break
		}
	}
	if firstNonZero == -1 {
		for i := 0; i < intWidth-1; i++ {
			b[i] = ' '
		}
	} else {
		for i := 0; i < firstNonZero; i++ {
			if i < intWidth-1 {
				b[i] = ' '
			}
		}
	}
	integerFormatted := string(b)
	fracStr := fmt.Sprintf("%0*d", fracWidth, fracPart)
	return string(signChar) + integerFormatted + "." + fracStr
}

func ReadPara() {
	if scanner == nil {
		WsEofFlag = "Y"
		return
	}
	if scanner.Scan() {
		line := scanner.Text()
		if len(line) < 8 {
			line = line + strings.Repeat(" ", 8-len(line))
		} else if len(line) > 8 {
			line = line[:8]
		}
		TempRecInst.TcSensor = line[0:4]
		tcFStr := line[4:8]
		var n int64
		for i := 0; i < len(tcFStr); i++ {
			c := tcFStr[i]
			if c >= '0' && c <= '9' {
				n = n*10 + int64(c-'0')
			} else {
				// space or other -> treat as 0
				n = n * 10
			}
		}
		TempRecInst.TcF = decimal.New(n, -1)
	} else {
		if err := scanner.Err(); err != nil {
			fmt.Fprintf(os.Stderr, "read error: %v\n", err)
			os.Exit(1)
		}
		WsEofFlag = "Y"
	}
}

func ProcessPara() {
	// COMPUTE WS-C ROUNDED = (TC-F - 32) * 5 / 9  -> (N-320)/18 rounded to 2 decimals
	n := TempRecInst.TcF.Shift(1).IntPart() // N = TC-F *10
	numerator := (n - 320) * 100            // (N-320)*100
	denom := int64(18)
	sign := int64(1)
	absNum := numerator
	if absNum < 0 {
		sign = -1
		absNum = -absNum
	}
	quot := absNum / denom
	rem := absNum % denom
	if rem*2 >= denom {
		quot++
	}
	yRounded := sign * quot // scaled by 100
	// high-order truncation for PIC S9(3)V99 : 3 int +2 frac = total 100000
	totalPow := int64(100000)
	absY := yRounded
	if absY < 0 {
		absY = -absY
	}
	if absY >= totalPow {
		absY = absY % totalPow
		if yRounded < 0 {
			yRounded = -absY
		} else {
			yRounded = absY
		}
		if yRounded == 0 {
			// normalize -0 to 0
		}
	}
	WsC = decimal.New(yRounded, -2)
	if WsC.Sign() < 0 {
		WsFreeze = (WsFreeze + 1) % 100
	}
	WsCount = (WsCount + 1) % 100
	WsFEd = formatZZ9_9(TempRecInst.TcF)
	WsCEd = formatMinusZZ9_99(WsC)
	fmt.Printf("%s %sF %sC\n", TempRecInst.TcSensor, WsFEd, WsCEd)
	ReadPara()
}

func MainPara() {
	var err error
	tempFile, err = os.Open("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed to open input.dat: %v\n", err)
		os.Exit(1)
	}
	scanner = bufio.NewScanner(tempFile)
	ReadPara()
	for !InputDone() {
		ProcessPara()
	}
	tempFile.Close()
	fmt.Printf("READINGS: %02d BELOW ZERO: %02d\n", WsCount, WsFreeze)
}

func main() {
	MainPara()
}
